/* The picker is handled at capture phase as well as during initial render.
   This makes every route replace its full page body even after a cached visit. */
function forceCompleteLanguage(lang){
  const choice=copy[lang]?lang:'en';
  setLanguage(choice);
  requestAnimationFrame(()=>{
    if(window.applyPikoPageLanguage)window.applyPikoPageLanguage(choice);
  });
}
function catchLanguagePicker(event){
  const picker=event.target;
  if(picker instanceof HTMLSelectElement&&picker.classList.contains('language')){
    forceCompleteLanguage(picker.value);
  }
}
/* Register at document level as well as on the select itself. This survives
   cached page restores and browser translation extensions that rebind form
   controls, while keeping the visitor on the current route. */
document.addEventListener('input',catchLanguagePicker,true);
document.addEventListener('change',catchLanguagePicker,true);
/* One native selector controls the whole current document.  This is deliberately
   independent of browser/third-party translation: it never navigates, reloads
   or removes a section. */
function bindNativeLanguageSelector(){
  const picker=document.querySelector('.language');
  if(!picker)return;
  const applyCurrentPage=()=>{
    const choice=copy[picker.value]?picker.value:'en';
    picker.value=choice;
    forceCompleteLanguage(choice);
    document.documentElement.dataset.language=choice;
  };
  picker.oninput=applyCurrentPage;
  picker.onchange=applyCurrentPage;
  applyCurrentPage();
}
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',bindNativeLanguageSelector,{once:true});
}else{
  bindNativeLanguageSelector();
}
window.addEventListener('pageshow',()=>{
  requestAnimationFrame(bindNativeLanguageSelector);
});

